/**
 * VibeLog Cloudflare Worker — PR3 (Task C)
 *
 * Stores the published snapshot in KV and serves the public /live page 24/7.
 *
 * Bindings (declared in wrangler.toml):
 *   SNAPSHOTS    — KV namespace for the snapshot
 *   PUBLISH_TOKEN — secret (set via `wrangler secret put PUBLISH_TOKEN`)
 *
 * Routes:
 *   POST /publish              — ingest a new snapshot (token-gated)
 *   GET  /state.json           — snapshot.state (costUsd stripped unless opted in)
 *   GET  /api/profile.json     — { profile: snapshot.profile }
 *   GET  /api/theme.json       — { vars: snapshot.theme } (ignores ?page=)
 *   GET  /                     — 301 to https://vibelogs.dev/ (the one landing page)
 *   GET  /live                 — live.html (the public profile, via static assets binding)
 *   GET  /embed                — embed.html (the G4 widget, via assets binding)
 *   GET  /embed.js             — loader script (auto-served from worker/public/)
 *
 * Security notes:
 *   - Only POST /publish writes; it is token-gated with a constant-time compare.
 *   - All GETs are public read-only; the snapshot surface contains no secrets.
 *   - Dollar spend (state.stats.costUsd) is stripped from /state.json unless the
 *     Worker itself opts in with PUBLIC_SHOW_COST = "true", so an old or
 *     misconfigured agent can never publish it.
 *   - HEAD is answered like GET without a body; every response carries the
 *     landing page's security headers (the /embed widget stays framable).
 *   - PUBLISH_TOKEN is never logged.
 */

import { SNAPSHOT_KEY } from "./keys.ts";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface Env {
  /** KV namespace for the snapshot. */
  SNAPSHOTS: KVNamespace;
  /** Secret token checked on POST /publish. Set via `wrangler secret put`. */
  PUBLISH_TOKEN: string;
  /** Static assets binding — serves files from worker/public/. */
  ASSETS: Fetcher;
  /** Optional var: "true" lets /state.json carry stats.costUsd. Default: stripped. */
  PUBLIC_SHOW_COST?: string;
}

/** Where the Worker's root sends visitors: the single marketing site. */
const LANDING_URL = "https://vibelogs.dev/";

/** The shape written by POST /publish and read back on GET routes. */
interface Snapshot {
  state: Record<string, unknown>;
  profile: Record<string, unknown>;
  theme: Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// Pure helpers (exported for unit tests)
// ---------------------------------------------------------------------------


/**
 * Constant-time string equality — prevents timing attacks on the token compare.
 *
 * Algorithm:
 *   1. If lengths differ, still compare a dummy pair so timing is consistent,
 *      then return false. (Do NOT early-return on length mismatch alone.)
 *   2. Walk the longer of the two strings char-by-char, XOR-accumulating
 *      differences so no short-circuit is possible.
 */
export function timingSafeEqualStr(a: string, b: string): boolean {
  // Determine a fixed iteration count based on the longer string.
  const len = Math.max(a.length, b.length);
  let diff = a.length ^ b.length; // non-zero if lengths differ
  for (let i = 0; i < len; i++) {
    // Use 0 as a stand-in for out-of-bounds chars; both sides get 0 if both
    // are short, which XORs to 0 (no spurious diff for equal short strings).
    const ca = a.charCodeAt(i) || 0;
    const cb = b.charCodeAt(i) || 0;
    diff |= ca ^ cb;
  }
  return diff === 0;
}

/** Route kinds understood by this worker. */
export type RouteKind =
  | "publish"
  | "state"
  | "profile"
  | "theme"
  | "home"
  | "page"
  | "embed"
  | "not_found";

/**
 * Map (method, pathname) → RouteKind.
 * Pure; usable in tests without a live Worker runtime.
 */
export function routeKind(method: string, pathname: string): RouteKind {
  // HEAD is GET without a body (answered in the fetch handler).
  const m = method.toUpperCase() === "HEAD" ? "GET" : method.toUpperCase();
  // Normalise trailing slash for comparison, but keep "/" itself.
  const p = pathname.length > 1 ? pathname.replace(/\/$/, "") : pathname;

  if (m === "POST" && p === "/publish") return "publish";
  if (m === "GET" && p === "/state.json") return "state";
  if (m === "GET" && p === "/api/profile.json") return "profile";
  if (m === "GET" && p === "/api/theme.json") return "theme";
  // "/" is the marketing front door (landing.html); "/live" is the public
  // profile (live.html). Keeping them distinct lets a stranger who lands on the
  // root learn what VibeLog is + grab it from GitHub, while shared links go to /live.
  if (m === "GET" && (p === "/" || p === "/landing")) return "home";
  if (m === "GET" && p === "/live") return "page";
  // The G4 embed widget. /embed.js is a real file served directly by the
  // static-assets binding; only the extensionless /embed page needs a rewrite.
  if (m === "GET" && p === "/embed") return "embed";
  return "not_found";
}

// ---------------------------------------------------------------------------
// Snapshot field extractors (exported for unit tests)
// ---------------------------------------------------------------------------

export function extractState(snap: Snapshot, opts: { showCost?: boolean } = {}): string {
  const state = snap.state ?? {};
  const stats = state.stats;
  if (opts.showCost || !stats || typeof stats !== "object" || !("costUsd" in stats)) {
    return JSON.stringify(state);
  }
  const { costUsd: _hidden, ...publicStats } = stats as Record<string, unknown>;
  return JSON.stringify({ ...state, stats: publicStats });
}

export function extractProfile(snap: Snapshot): string {
  return JSON.stringify({ profile: snap.profile ?? {} });
}

export function extractTheme(snap: Snapshot): string {
  return JSON.stringify({ vars: snap.theme ?? {} });
}

// ---------------------------------------------------------------------------
// Cold/empty defaults (returned when KV has no snapshot yet)
// ---------------------------------------------------------------------------

const EMPTY_STATE = JSON.stringify({});
const EMPTY_PROFILE = JSON.stringify({ profile: {} });
const EMPTY_THEME = JSON.stringify({ vars: {} });

// ---------------------------------------------------------------------------
// Response helpers
// ---------------------------------------------------------------------------

/** Same baseline as vibelogs.dev. X-Frame-Options is added per route (not /embed). */
const SECURITY_HEADERS: Record<string, string> = {
  "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
};

/** Stamp security headers (and drop the body for HEAD) on any response. */
export function finalize(res: Response, opts: { head: boolean; framable: boolean }): Response {
  const headers = new Headers(res.headers);
  for (const [k, v] of Object.entries(SECURITY_HEADERS)) headers.set(k, v);
  if (!opts.framable) headers.set("X-Frame-Options", "DENY");
  return new Response(opts.head ? null : res.body, { status: res.status, statusText: res.statusText, headers });
}

const JSON_HEADERS = {
  "Content-Type": "application/json; charset=utf-8",
  "Access-Control-Allow-Origin": "*",
  "Cache-Control": "public, max-age=30",
} as const;

function jsonResponse(body: string, status = 200): Response {
  return new Response(body, { status, headers: JSON_HEADERS });
}

/**
 * Serve a JSON GET through Cloudflare's edge cache (`caches.default`) so repeated
 * viewer polls don't re-read KV. The public page polls /state.json every ~1.5s;
 * without this every poll is a KV read (the free tier allows 100k reads/day, so
 * a few all-day tabs could approach it). With this, within the JSON_HEADERS
 * max-age window the response is served straight from the edge — zero KV reads —
 * and we only hit KV on a cache miss (≈ once per TTL per data-center).
 *
 * The cache key is normalised to the pathname (query dropped) so /api/theme.json
 * variants (?page=live|overlay|…) share one entry. Staleness is bounded by the
 * 30s TTL — comfortably under the publish cadence (≥300s), so viewers still see
 * a new snapshot within ~30s of it landing.
 *
 * Defensive: `caches` only exists in the Workers runtime. Under `node --test`
 * (where the round-trip tests drive this handler) it's undefined, so we fall
 * back to building the body directly — the tests still exercise the KV path.
 */
async function cachedJson(
  request: Request,
  ctx: ExecutionContext | undefined,
  build: () => Promise<string>
): Promise<Response> {
  const hasEdgeCache = typeof caches !== "undefined" && !!caches.default;
  if (!hasEdgeCache) return jsonResponse(await build());

  const cache = caches.default;
  const keyUrl = new URL(request.url);
  keyUrl.search = "";
  const cacheKey = new Request(keyUrl.toString(), { method: "GET" });

  const hit = await cache.match(cacheKey);
  if (hit) return hit;

  const res = jsonResponse(await build());
  // Populate the cache off the response path when we can (waitUntil); otherwise
  // await so the write isn't dropped.
  const put = cache.put(cacheKey, res.clone());
  if (ctx?.waitUntil) ctx.waitUntil(put);
  else await put;
  return res;
}

function errorResponse(status: number, message: string): Response {
  return new Response(JSON.stringify({ error: message }), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8" },
  });
}

// ---------------------------------------------------------------------------
// POST /publish handler
// ---------------------------------------------------------------------------

const MAX_BODY_BYTES = 256 * 1024; // 256 KB

async function handlePublish(request: Request, env: Env): Promise<Response> {
  // 1. Token check — constant-time compare
  const authHeader = request.headers.get("Authorization") ?? "";
  const token = authHeader.startsWith("Bearer ") ? authHeader.slice(7) : "";
  if (!timingSafeEqualStr(token, env.PUBLISH_TOKEN)) {
    return errorResponse(403, "Forbidden");
  }

  // 2. Size cap — reject oversized bodies before reading them
  const contentLength = parseInt(request.headers.get("Content-Length") ?? "0", 10);
  if (contentLength > MAX_BODY_BYTES) {
    return errorResponse(413, "Payload too large");
  }

  // 3. Read + parse body
  let bodyText: string;
  try {
    // Clone and consume with a size guard — even if Content-Length is absent/wrong
    const reader = request.body?.getReader();
    if (!reader) return errorResponse(400, "Empty body");

    const chunks: Uint8Array[] = [];
    let totalBytes = 0;
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (value) {
        totalBytes += value.byteLength;
        if (totalBytes > MAX_BODY_BYTES) {
          return errorResponse(413, "Payload too large");
        }
        chunks.push(value);
      }
    }
    bodyText = new TextDecoder().decode(
      chunks.reduce((acc, c) => {
        const merged = new Uint8Array(acc.byteLength + c.byteLength);
        merged.set(acc, 0);
        merged.set(c, acc.byteLength);
        return merged;
      }, new Uint8Array(0))
    );
  } catch {
    return errorResponse(400, "Failed to read body");
  }

  // 4. Parse JSON + sanity-check structure
  let snapshot: Snapshot;
  try {
    const parsed = JSON.parse(bodyText) as unknown;
    if (
      !parsed ||
      typeof parsed !== "object" ||
      !("state" in parsed) ||
      !("profile" in parsed) ||
      !("theme" in parsed)
    ) {
      return errorResponse(400, "Body must be JSON with state, profile, theme fields");
    }
    snapshot = parsed as Snapshot;
  } catch {
    return errorResponse(400, "Invalid JSON");
  }

  // 5. Write to KV
  await env.SNAPSHOTS.put(SNAPSHOT_KEY, JSON.stringify(snapshot));

  return new Response(null, { status: 204 });
}

// ---------------------------------------------------------------------------
// GET handlers (read from KV)
// ---------------------------------------------------------------------------

async function getSnapshot(env: Env): Promise<Snapshot | null> {
  const raw = await env.SNAPSHOTS.get(SNAPSHOT_KEY);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as Snapshot;
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Main fetch handler
// ---------------------------------------------------------------------------

export default {
  // ctx is optional only so the round-trip tests can call fetch(req, env) under
  // plain Node; the Workers runtime always passes it. A 3-arg fn is assignable
  // to ExportedHandler's required-ctx signature.
  async fetch(request: Request, env: Env, ctx?: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    const kind = routeKind(request.method, url.pathname);
    const res = await route(kind, request, env, ctx);
    return finalize(res, { head: request.method.toUpperCase() === "HEAD", framable: kind === "embed" });
  },
} satisfies ExportedHandler<Env>;

async function route(kind: RouteKind, request: Request, env: Env, ctx?: ExecutionContext): Promise<Response> {
  // CORS pre-flight for GET routes (unlikely but tidy)
  if (request.method === "OPTIONS") {
    return new Response(null, {
      headers: {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Methods": "GET, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type",
      },
    });
  }

  switch (kind) {
    case "publish":
      return handlePublish(request, env);

    case "state":
      return cachedJson(request, ctx, async () => {
        const snap = await getSnapshot(env);
        return snap ? extractState(snap, { showCost: env.PUBLIC_SHOW_COST === "true" }) : EMPTY_STATE;
      });

    case "profile":
      return cachedJson(request, ctx, async () => {
        const snap = await getSnapshot(env);
        return snap ? extractProfile(snap) : EMPTY_PROFILE;
      });

    case "theme":
      return cachedJson(request, ctx, async () => {
        const snap = await getSnapshot(env);
        return snap ? extractTheme(snap) : EMPTY_THEME;
      });

    case "home":
      // One landing page: the old copy that lived here drifted from vibelogs.dev.
      return Response.redirect(LANDING_URL, 301);

    case "page":
    case "embed": {
      // Serve a static HTML page from the assets binding: "/live" is the
      // public profile (live.html), "/embed" the G4 widget (embed.html). The
      // extra hop rewrites the extensionless route and stamps Cache-Control.
      const file = kind === "embed" ? "/embed.html" : "/live.html";
      const assetUrl = new URL(request.url);
      assetUrl.pathname = file;
      const assetReq = new Request(assetUrl.toString(), { method: "GET", headers: request.headers });
      const assetRes = await env.ASSETS.fetch(assetReq);
      const headers = new Headers(assetRes.headers);
      headers.set("Cache-Control", "public, max-age=30");
      return new Response(assetRes.body, {
        status: assetRes.status,
        headers,
      });
    }

    default:
      return errorResponse(404, "Not found");
  }
}
